const pptxgen = require('pptxgenjs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

const theme = {
  primary: "264653",   // dark teal - titles
  secondary: "2a9d8f", // teal accent
  accent: "e9c46a",    // gold highlight
  light: "f4a261",     // orange light
  bg: "edf6f9"         // light blue-white background
};

// Compile all 7 slides
for (let i = 1; i <= 7; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: './output/final_deck.pptx' })
  .then(() => console.log('Created: ./output/final_deck.pptx'))
  .catch(err => console.error('Error:', err));

