1	const pptxgen = require("pptxgenjs");
2	
3	const slideConfig = {
4	  title: "App Ecosystem: Who's Calling These Models",
5	  category: "content",
6	  pageNumber: 6
7	};
8	
9	function createSlide(pres, theme) {
10	  const slide = pres.addSlide();
11	  slide.dim = "10 x 5.625";
12	
13	  // Background
14	  slide.addShape(pptxgen.ShapeType.rect, {
15	    x: 0, y: 0, w: "100%", h: "100%",
16	    fill: { color: theme.bg }
17	  });
18	
19	  // Title
20	  slide.addText("App Ecosystem: Who's Calling These Models", {
21	    x: 0.5, y: 0.3, w: 9, h: 0.6,
22	    fontSize: 28, fontFace: "Arial",
23	    color: theme.primary, bold: true
24	  });
25	
26	  // Subtitle / Key insight
27	  slide.addText("5 of top 10 apps are AI coding tools — coding agents have become the largest LLM consumption scenario", {
28	    x: 0.5, y: 0.9, w: 8.5, h: 0.4,
29	    fontSize: 14, fontFace: "Arial",
30	    color: theme.secondary, italic: true
31	  });
32	
33	  // Data table for top 10 apps
34	  const apps = [
35	    { rank: 1, name: "OpenClaw", tokens: "829B", type: "coding" },
36	    { rank: 2, name: "Kilo Code", tokens: "271B", type: "coding" },
37	    { rank: 3, name: "Claude Code", tokens: "78B", type: "coding" },
38	    { rank: 4, name: "Cline", tokens: "69.1B", type: "coding" },
39	    { rank: 5, name: "Janitor AI", tokens: "29.2B", type: "entertainment" },
40	    { rank: 6, name: "ISEKAI ZERO", tokens: "28.8B", type: "entertainment" },
41	    { rank: 7, name: "Descript", tokens: "27B", type: "entertainment" },
42	    { rank: 8, name: "Hermes Agent", tokens: "19.2B", type: "coding" },
43	    { rank: 9, name: "Roo Code", tokens: "11.8B", type: "coding" },
44	    { rank: 10, name: "Scripty", tokens: "9.95B", type: "coding" }
45	  ];
46	
47	  // Left side: Bar chart visualization
48	  const chartX = 0.5;
49	  const chartY = 1.5;
50	  const chartW = 5.5;
51	  const barH = 0.32;
52	  const barGap = 0.06;
53	  const maxTokens = 829;
54	
55	  apps.forEach((app, i) => {
56	    const y = chartY + i * (barH + barGap);
57	    const barWidth = (parseFloat(app.tokens) / maxTokens) * (chartW - 1.5);
58	
59	    // Bar background (track)
60	    slide.addShape(pptxgen.ShapeType.rect, {
61	      x: chartX + 1.0, y: y, w: chartW - 1.5, h: barH,
62	      fill: { color: "e0e0e0" }
63	    });
64	
65	    // Bar fill
66	    const barColor = app.type === "coding" ? theme.secondary : theme.light;
67	    slide.addShape(pptxgen.ShapeType.rect, {
68	      x: chartX + 1.0, y: y, w: barWidth, h: barH,
69	      fill: { color: barColor }
70	    });
71	
72	    // Rank number
73	    slide.addText(app.rank.toString(), {
74	      x: chartX, y: y, w: 0.35, h: barH,
75	      fontSize: 12, fontFace: "Arial",
76	      color: theme.primary, bold: true,
77	      align: "center", valign: "middle"
78	    });
79	
80	    // App name
81	    slide.addText(app.name, {
82	      x: chartX + 0.4, y: y, w: 0.9, h: barH,
83	      fontSize: 10, fontFace: "Arial",
84	      color: theme.primary,
85	      align: "left", valign: "middle"
86	    });
87	
88	    // Token volume at end of bar
89	    slide.addText(app.tokens, {
90	      x: chartX + 1.0 + barWidth + 0.05, y: y, w: 0.6, h: barH,
91	      fontSize: 9, fontFace: "Arial",
92	      color: theme.primary, bold: true,
93	      align: "left", valign: "middle"
94	    });
95	
96	    // Badge for top 4 coding tools
97	    if (app.rank <= 4) {
98	      slide.addShape(pptxgen.ShapeType.rect, {
99	        x: chartX + 4.2, y: y + 0.02, w: 0.9, h: barH - 0.04,
100	        fill: { color: theme.secondary },
101	        rectRadius: 0.05
102	      });
103	      slide.addText("CODE", {
104	        x: chartX + 4.2, y: y + 0.02, w: 0.9, h: barH - 0.04,
105	        fontSize: 7, fontFace: "Arial",
106	        color: "ffffff", bold: true,
107	        align: "center", valign: "middle"
108	      });
109	    } else if (app.type === "entertainment") {
110	      slide.addShape(pptxgen.ShapeType.rect, {
111	        x: chartX + 4.2, y: y + 0.02, w: 1.1, h: barH - 0.04,
112	        fill: { color: theme.light },
113	        rectRadius: 0.05
114	      });
115	      slide.addText("ENTERTAIN", {
116	        x: chartX + 4.2, y: y + 0.02, w: 1.1, h: barH - 0.04,
117	        fontSize: 7, fontFace: "Arial",
118	        color: "ffffff", bold: true,
119	        align: "center", valign: "middle"
120	      });
121	    } else {
122	      slide.addShape(pptxgen.ShapeType.rect, {
123	        x: chartX + 4.2, y: y + 0.02, w: 0.9, h: barH - 0.04,
124	        fill: { color: theme.accent },
125	        rectRadius: 0.05
126	      });
127	      slide.addText("CODE", {
128	        x: chartX + 4.2, y: y + 0.02, w: 0.9, h: barH - 0.04,
129	        fontSize: 7, fontFace: "Arial",
130	        color: theme.primary, bold: true,
131	        align: "center", valign: "middle"
132	      });
133	    }
134	  });
135	
136	  // Right side: Callout box
137	  const calloutX = 6.4;
138	  const calloutY = 1.6;
139	  const calloutW = 3.2;
140	  const calloutH = 1.8;
