const pptxgen = require("pptxgenjs");

const slideConfig = {
  title: "App Ecosystem: Who's Calling These Models",
  category: "content",
  pageNumber: 6
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.dim = "10 x 5.625";

  // Background
  slide.addShape(pptxgen.ShapeType.rect, {
    x: 0, y: 0, w: "100%", h: "100%",
    fill: { color: theme.bg }
  });

  // Title
  slide.addText("App Ecosystem: Who's Calling These Models", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Arial",
    color: theme.primary, bold: true
  });

  // Subtitle / Key insight
  slide.addText("5 of top 10 apps are AI coding tools — coding agents have become the largest LLM consumption scenario", {
    x: 0.5, y: 0.9, w: 8.5, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: theme.secondary, italic: true
  });

  // Data table for top 10 apps
  const apps = [
    { rank: 1, name: "OpenClaw", tokens: "829B", type: "coding" },
    { rank: 2, name: "Kilo Code", tokens: "271B", type: "coding" },
    { rank: 3, name: "Claude Code", tokens: "78B", type: "coding" },
    { rank: 4, name: "Cline", tokens: "69.1B", type: "coding" },
    { rank: 5, name: "Janitor AI", tokens: "29.2B", type: "entertainment" },
    { rank: 6, name: "ISEKAI ZERO", tokens: "28.8B", type: "entertainment" },
    { rank: 7, name: "Descript", tokens: "27B", type: "entertainment" },
    { rank: 8, name: "Hermes Agent", tokens: "19.2B", type: "coding" },
    { rank: 9, name: "Roo Code", tokens: "11.8B", type: "coding" },
    { rank: 10, name: "Scripty", tokens: "9.95B", type: "coding" }
  ];

  // Left side: Bar chart visualization
  const chartX = 0.5;
  const chartY = 1.5;
  const chartW = 5.5;
  const barH = 0.32;
  const barGap = 0.06;
  const maxTokens = 829;

  apps.forEach((app, i) => {
    const y = chartY + i * (barH + barGap);
    const barWidth = (parseFloat(app.tokens) / maxTokens) * (chartW - 1.5);

    // Bar background (track)
    slide.addShape(pptxgen.ShapeType.rect, {
      x: chartX + 1.0, y: y, w: chartW - 1.5, h: barH,
      fill: { color: "e0e0e0" }
    });

    // Bar fill
    const barColor = app.type === "coding" ? theme.secondary : theme.light;
    slide.addShape(pptxgen.ShapeType.rect, {
      x: chartX + 1.0, y: y, w: barWidth, h: barH,
      fill: { color: barColor }
    });

    // Rank number
    slide.addText(app.rank.toString(), {
      x: chartX, y: y, w: 0.35, h: barH,
      fontSize: 12, fontFace: "Arial",
      color: theme.primary, bold: true,
      align: "center", valign: "middle"
    });

    // App name
    slide.addText(app.name, {
      x: chartX + 0.4, y: y, w: 0.9, h: barH,
      fontSize: 10, fontFace: "Arial",
      color: theme.primary,
      align: "left", valign: "middle"
    });

    // Token volume at end of bar
    slide.addText(app.tokens, {
      x: chartX + 1.0 + barWidth + 0.05, y: y, w: 0.6, h: barH,
      fontSize: 9, fontFace: "Arial",
      color: theme.primary, bold: true,
      align: "left", valign: "middle"
    });

    // Badge for top 4 coding tools
    if (app.rank <= 4) {
      slide.addShape(pptxgen.ShapeType.rect, {
        x: chartX + 4.2, y: y + 0.02, w: 0.9, h: barH - 0.04,
        fill: { color: theme.secondary },
        rectRadius: 0.05
      });
      slide.addText("CODE", {
        x: chartX + 4.2, y: y + 0.02, w: 0.9, h: barH - 0.04,
        fontSize: 7, fontFace: "Arial",
        color: "ffffff", bold: true,
        align: "center", valign: "middle"
      });
    } else if (app.type === "entertainment") {
      slide.addShape(pptxgen.ShapeType.rect, {
        x: chartX + 4.2, y: y + 0.02, w: 1.1, h: barH - 0.04,
        fill: { color: theme.light },
        rectRadius: 0.05
      });
      slide.addText("ENTERTAIN", {
        x: chartX + 4.2, y: y + 0.02, w: 1.1, h: barH - 0.04,
        fontSize: 7, fontFace: "Arial",
        color: "ffffff", bold: true,
        align: "center", valign: "middle"
      });
    } else {
      slide.addShape(pptxgen.ShapeType.rect, {
        x: chartX + 4.2, y: y + 0.02, w: 0.9, h: barH - 0.04,
        fill: { color: theme.accent },
        rectRadius: 0.05
      });
      slide.addText("CODE", {
        x: chartX + 4.2, y: y + 0.02, w: 0.9, h: barH - 0.04,
        fontSize: 7, fontFace: "Arial",
        color: theme.primary, bold: true,
        align: "center", valign: "middle"
      });
    }
  });

  // Right side: Callout box
  const calloutX = 6.4;
  const calloutY = 1.6;
  const calloutW = 3.2;
  const calloutH = 1.8;

  // Callout background
  slide.addShape(pptxgen.ShapeType.rect, {
    x: calloutX, y: calloutY, w: calloutW, h: calloutH,
    fill: { color: theme.primary },
    rectRadius: 0.1
  });

  // Callout accent stripe
  slide.addShape(pptxgen.ShapeType.rect, {
    x: calloutX, y: calloutY, w: 0.12, h: calloutH,
    fill: { color: theme.accent }
  });

  // Callout title
  slide.addText("KEY FINDING", {
    x: calloutX + 0.25, y: calloutY + 0.15, w: calloutW - 0.4, h: 0.3,
    fontSize: 10, fontFace: "Arial",
    color: theme.accent, bold: true
  });

  // Callout big number
  slide.addText("829B", {
    x: calloutX + 0.25, y: calloutY + 0.45, w: calloutW - 0.4, h: 0.6,
    fontSize: 36, fontFace: "Arial",
    color: "ffffff", bold: true
  });

  // Callout description
  slide.addText("tokens/day consumed by OpenClaw — nearly 3x the second-place app (Kilo Code at 271B)", {
    x: calloutX + 0.25, y: calloutY + 1.1, w: calloutW - 0.5, h: 0.55,
    fontSize: 11, fontFace: "Arial",
    color: theme.bg
  });

  // Right side: Legend
  const legendX = 6.5;
  const legendY = 3.7;

  slide.addText("Legend:", {
    x: legendX, y: legendY, w: 1, h: 0.25,
    fontSize: 9, fontFace: "Arial",
    color: theme.primary, bold: true
  });

  // Coding badge sample
  slide.addShape(pptxgen.ShapeType.rect, {
    x: legendX + 0.6, y: legendY + 0.03, w: 0.7, h: 0.2,
    fill: { color: theme.secondary },
    rectRadius: 0.05
  });
  slide.addText("Coding Agent", {
    x: legendX + 1.35, y: legendY, w: 1.2, h: 0.25,
    fontSize: 9, fontFace: "Arial",
    color: theme.primary
  });

  // Entertainment badge sample
  slide.addShape(pptxgen.ShapeType.rect, {
    x: legendX + 0.6, y: legendY + 0.32, w: 0.7, h: 0.2,
    fill: { color: theme.light },
    rectRadius: 0.05
  });
  slide.addText("Entertainment", {
    x: legendX + 1.35, y: legendY + 0.3, w: 1.2, h: 0.25,
    fontSize: 9, fontFace: "Arial",
    color: theme.primary
  });

  // Stats summary at bottom right
  const statsY = 4.4;
  slide.addShape(pptxgen.ShapeType.rect, {
    x: 6.5, y: statsY, w: 3.1, h: 0.7,
    fill: { color: theme.accent, transparency: 20 },
    line: { color: theme.accent, width: 1 },
    rectRadius: 0.08
  });

  slide.addText("Coding apps represent 70% of top 10 token consumption", {
    x: 6.6, y: statsY + 0.1, w: 2.9, h: 0.5,
    fontSize: 10, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "center", valign: "middle"
  });

  // Page number badge at x: 9.3", y: 5.1"
  slide.addShape(pptxgen.ShapeType.ellipse, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.3,
    fill: { color: theme.secondary }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.3,
    fontSize: 11, fontFace: "Arial",
    color: "ffffff", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

